// Obtener datos de cotizaciones
const rates = $input.all();

// Monto de ejemplo para conversión
const exampleUsd = 1000;

// Obtener fecha y hora actual
const now = new Date();
const formattedDate = now.toLocaleString('es-AR', {
  timeZone: 'America/Argentina/Buenos_Aires',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit'
});

// Construir mensaje
let message = '📊 USD Salary Monitor Argentina

';
message += '✅ App Status: Online
';
message += '🔗 https://calculadora-ingresos-usd.vercel.app/

';
message += '💰 Cotizaciones de venta:

';

// Agregar cada tipo de dólar
rates.forEach((rate) => {
  const name = rate.json.nombre;
  const sell = rate.json.venta;
  const emoji = getEmoji(rate.json.casa);
  const formattedSell = formatCurrency(sell);
  const exampleArs = formatCurrency(sell * exampleUsd);

  message += `${emoji} ${name}: ${formattedSell} ARS
`;
});

message += '
💵 Ejemplo USD ' + formatNumber(exampleUsd) + ':
';

rates.forEach((rate) => {
  const name = rate.json.nombre;
  const sell = rate.json.venta;
  const exampleArs = formatCurrency(sell * exampleUsd);
  const shortName = getShortName(rate.json.casa);

  message += '   ' + shortName + ': ' + exampleArs + ' ARS
';
});

message += '
📅 ' + formattedDate + '

';
message += '⚠️ Las cotizaciones son informativas y pueden variar.';

// Funciones auxiliares
function getEmoji(casa) {
  const emojis = {
    'oficial': '🏛️',
    'blue': '💙',
    'bolsa': '📈',
    'cripto': '₿'
  };
  return emojis[casa] || '💵';
}

function getShortName(casa) {
  const names = {
    'oficial': 'Oficial',
    'blue': 'Blue',
    'bolsa': 'MEP',
    'cripto': 'Cripto'
  };
  return names[casa] || casa;
}

function formatCurrency(value) {
  return new Intl.NumberFormat('es-AR', {
    style: 'currency',
    currency: 'ARS',
    minimumFractionDigits: 0,
    maximumFractionDigits: 0
  }).format(value);
}

function formatNumber(value) {
  return new Intl.NumberFormat('es-AR').format(value);
}

// Retornar el mensaje
return [{ json: { message } }];
